class SuinSoapService
{
    /**
     * @var SoapClient
     */
    protected $_operacion, $_url, $_client, $_indixes;

    /**
     * @return mixed
     */
    public function getUrl()
    {
        $this->_url = "http://10.12.172.176/Convertidor/Service1.asmx?wsdl";
        return $this->_url;
    }

    /**
     * @param mixed $url
     */
    public function setUrl($url)
    {
        $this->_url = $url;
    }


    /**
     * @return mixed
     */
    public function getOperacion()
    {

        return $this->_operacion;
    }

    /**
     * @param mixed $operacion
     */
    public function setOperacion($operacion)
    {
        $this->_operacion = $operacion;
    }


    /**
     * SuinSoapService constructor.
     * @param null $url
     */
    public function __construct($url = null)
    {
        if ($url) {
            $this->setUrl($url);
        }
        $this->_client = new SoapClient($this->getUrl());
        ini_set('default_socket_timeout', (Integer)300);
        $this->_indixes = array(
            'idsuin' => '',
            'numid' => '',
            'nombre' => '',
            'snombre' => '',
            'papel' => '',
            'sapel' => '',
            'sexo' => '',
            'nompa' => '',
            'nomma' => '',
            'direccion' => '',
            'idprovinciares' => '',
            'idmunicipiores' => '',
            'nacionalidad' => '',
            'tomo' => '',
            'idcolorojos' => '',
            'idcolorpiel' => '',
            'idtipodocidentidad' => '',
            'foto' => '',
            'edad' => '',
            'fechanacimiento' => '',
            'nombreapellidos' => '',
        );
    }

    /**
     * @param $numid
     * @param null $nombre
     * @param null $snombre
     * @param null $papel
     * @param null $sapel
     * @return array
     * @throws Exception
     */
    public function buscarByParams($numid, $nombre = null, $snombre = null, $papel = null, $sapel = null)
    {
        try {
            ini_set('default_socket_timeout', (Integer)300);
            $response = array();
            if ($this->isRunning()) {
                if ($numid && $nombre != null || $snombre != null || $papel != null || $sapel != null) {
                    $this->setOperacion("SUIN02");
                    $request = '<Envelope xsi:schemaLocation="http://schemas.xmlsoap.org/soap/envelope/ SearchNationalPersonByBiographic.xsd" xmlns="http://schemas.xmlsoap.org/soap/envelope/" xmlns:m="http://CommonServices" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                                    <Body>
                                        <m:SearchNationalPersonByBiographic>
                                            <m:identityNumber>' . $numid . '</m:identityNumber>
                                            <m:firstName>' . $nombre . '</m:firstName>
                                            <m:secondName>' . $snombre . '</m:secondName>
                                            <m:firstSurName>' . $papel . '</m:firstSurName>
                                            <m:secondSurName>' . $sapel . '</m:secondSurName>
                                        </m:SearchNationalPersonByBiographic>
                                    </Body>
                                </Envelope>';
                    $ent = $this->_client->sendRequest(array("operacion" => $this->getOperacion(), "xml" => $request));
                    $resultado = json_decode($ent->sendRequestResult);
					$response = array();
                    if (count($resultado) > 0 && !empty($resultado[0]->IdSuin)) {
                        $idsuin = $resultado[0]->IdSuin;
                        if ($resultado[0]->FechaNacimiento) {
                            $fecha = explode('T', $resultado[0]->FechaNacimiento);
                            $resultado[0]->FechaNacimiento = $fecha[0];
                        }
                        if(!empty($resultado[0]->SegundoNombre))
                            $resultado[0]->NombreApellidos = $resultado[0]->PrimerNombre.' '.$resultado[0]->SegundoNombre.'                                                                 '.$resultado[0]->PrimerApellido.' '.$resultado[0]->SegundoApellido;
                        else
                            $resultado[0]->NombreApellidos = $resultado[0]->PrimerNombre.' '.$resultado[0]->PrimerApellido.'                                                                '.$resultado[0]->SegundoApellido;

                        $this->setOperacion("SUIN03");
                        $req = '<Envelope xsi:schemaLocation="http://schemas.xmlsoap.org/soap/envelope/ GetImageByPerson.xsd" xmlns="http://schemas.xmlsoap.org/soap/envelope/" xmlns:m="http://CommonServices" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                                <Body>
                                    <m:GetImageByPerson>
                                        <m:idPerson>' . $idsuin . '</m:idPerson>
                                        <m:personImageTypeId>1</m:personImageTypeId>
                                    </m:GetImageByPerson>
                                </Body>
                            </Envelope>';
                        $foto = $this->_client->sendRequest(array('operacion' => $this->getOperacion(), 'xml' => $req));
                        $foto1 = json_decode(json_encode($foto), true);
                        $result = json_decode($foto1['sendRequestResult']);
                        if (is_array($result))
                            $resultado[0]->Foto = $result[0]->Foto;
                        else{
                            if($resultado[0]->Sexo == 'F')
                                $resultado[0]->Foto = "";
                            else
                                $resultado[0]->Foto = "";
                        }
                        $response = $this->reformatPerson($resultado);
                    }
                    return array('datos' => $response, 'cantidad' => count($response));
                } else {
                    $this->setOperacion("SUIN01");
                    $request = '<SOAP-ENV:Envelope xmlns:SOAP-ENV="http://schemas.xmlsoap.org/soap/envelope/" xmlns:SOAP-ENC="http://schemas.xmlsoap.org/soap/encoding/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema"><SOAP-ENV:Body><m:SearchPersonByIdentityNumber xmlns:m="http://CommonServices"><m:identityNumber>' . $numid . '</m:identityNumber></m:SearchPersonByIdentityNumber></SOAP-ENV:Body></SOAP-ENV:Envelope>';
                    $ent = $this->_client->sendRequest(array("operacion" => $this->getOperacion(), "xml" => $request));
					$resultado = json_decode($ent->sendRequestResult);

                    if (count($resultado) > 0 && !empty($resultado[0]->IdSuin)) {
                        $idsuin = $resultado[0]->IdSuin;
                        if ($resultado[0]->FechaNacimiento) {
                            $fecha = explode('T', $resultado[0]->FechaNacimiento);
                            $resultado[0]->FechaNacimiento = $fecha[0];
                        }
                        if(!empty($resultado[0]->SegundoNombre))
                            $resultado[0]->NombreApellidos = $resultado[0]->PrimerNombre.' '.$resultado[0]->SegundoNombre.' '.$resultado[0]->PrimerApellido.' '.$resultado[0]->SegundoApellido;
                        else
                            $resultado[0]->NombreApellidos = $resultado[0]->PrimerNombre.' '.$resultado[0]->PrimerApellido.' '.$resultado[0]->SegundoApellido;

                        $this->setOperacion("SUIN03");
                        $req = '<Envelope xsi:schemaLocation="http://schemas.xmlsoap.org/soap/envelope/ GetImageByPerson.xsd" xmlns="http://schemas.xmlsoap.org/soap/envelope/" xmlns:m="http://CommonServices" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                                <Body>
                                    <m:GetImageByPerson>
                                        <m:idPerson>' . $idsuin . '</m:idPerson>
                                        <m:personImageTypeId>1</m:personImageTypeId>
                                    </m:GetImageByPerson>
                                </Body>
                            </Envelope>';
                        $foto = $this->_client->sendRequest(array('operacion' => $this->getOperacion(), 'xml' => $req));
                        $foto1 = json_decode(json_encode($foto), true);
                        $result = json_decode($foto1['sendRequestResult']);
                        if (is_array($result))
                            $resultado[0]->Foto = $result[0]->Foto;
                        else{
                            if($resultado[0]->Sexo == 'F')
                                $resultado[0]->Foto = "";
                            else
                                $resultado[0]->Foto = "";
                        }
                        $response = $this->reformatPerson($resultado);
                    }
                    return array('datos' => $response, 'cantidad' => count($response));
                }

            } else {
                return array('expecion' => 'Error',
                    'msg' => 'El servicio no esta disponible. Por favor intente más tarde.');
            }

        } catch (Exception $e) {
            throw $e;
        }
    }

    public function buscarByParamsDatos($numid, $nombre = null, $snombre = null, $papel = null, $sapel = null)
    {
        try {
            ini_set('default_socket_timeout', (Integer)300);
            $response = array();
            if ($this->isRunning()) {
                if ($numid && $nombre != null || $snombre != null || $papel != null || $sapel != null) {
                    $this->setOperacion("SUIN02");
                    $request = '<Envelope xsi:schemaLocation="http://schemas.xmlsoap.org/soap/envelope/ SearchNationalPersonByBiographic.xsd" xmlns="http://schemas.xmlsoap.org/soap/envelope/" xmlns:m="http://CommonServices" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                                    <Body>
                                        <m:SearchNationalPersonByBiographic>
