                                            <m:firstName>' . $nombre . '</m:firstName>
                                            <m:secondName>' . $snombre . '</m:secondName>
                                            <m:firstSurName>' . $papel . '</m:firstSurName>
                                            <m:secondSurName>' . $sapel . '</m:secondSurName>
