                        $response = $this->reformatPerson($resultado);
                    }
                    return array('datos' => $response, 'cantidad' => count($response));
                } else {
                    $this->setOperacion("SUIN01");
                    $request = '<SOAP-ENV:Envelope xmlns:SOAP-ENV="http://schemas.xmlsoap.org/soap/envelope/" xmlns:SOAP-ENC="http://schemas.xmlsoap.org/soap/encoding/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema"><SOAP-ENV:Body><m:SearchPersonByIdentityNumber xmlns:m="http://CommonServices"><m:identityNumber>' . $numid . '</m:identityNumber></m:SearchPersonByIdentityNumber></SOAP-ENV:Body></SOAP-ENV:Envelope>';
                    $ent = $this->_client->sendRequest(array("operacion" => $this->getOperacion(), "xml" => $request));
                    $resultado = json_decode($ent->sendRequestResult);

                    if (count($resultado) > 0 && !empty($resultado[0]->IdSuin)) {
                        $idsuin = $resultado[0]->IdSuin;
                        if ($resultado[0]->FechaNacimiento) {
                            $fecha = explode('T', $resultado[0]->FechaNacimiento);
                            $resultado[0]->FechaNacimiento = $fecha[0];
                        }
                        if(!empty($resultado[0]->SegundoNombre))
                            $resultado[0]->NombreApellidos = $resultado[0]->PrimerNombre.' '.$resultado[0]->SegundoNombre.' '.$resultado[0]->PrimerApellido.' '.$resultado[0]->SegundoApellido;
                        else
                            $resultado[0]->NombreApellidos = $resultado[0]->PrimerNombre.' '.$resultado[0]->PrimerApellido.' '.$resultado[0]->SegundoApellido;

                        $response = $this->reformatPerson($resultado);
                    }
                    return array('datos' => $response, 'cantidad' => count($response));
                }

            } else {
                return array('expecion' => 'Error',
                    'msg' => 'El servicio no esta disponible. Por favor intente más tarde.');
            }

        } catch (Exception $e) {
            throw $e;
        }
    }

    /**
     * @return mixed
     * @throws Exception
     */
    public function isRunning()
    {
        try {
            ini_set('default_socket_timeout', (Integer)300);
            $bool = $this->_client->isRunning();
			if($bool->isRunningResult == '{success: True}'){
				return true;
			}else{
				return false;
			}
            //return $bool->isRunningResult;
        } catch (Exception $e) {
            throw $e;
        }
    }

    /**
     * @param $resultado
     * @return array
     * @throws Exception
     */
    private function reformatPerson($resultado)
    {
        try {
            $persona = array();
            if (isset($resultado->TypeError)) {
                return array('expecion' => 'Error',
                    'msg' => 'El servidor remoto devolvió una respuesta inesperada: (502) Bad Gateway.');
            } else {
                foreach ($resultado as $p => $val) {
                    foreach ($this->_indixes as $k => $v) {
                        switch ($k) {
                            case 'idsuin':
                                $persona[$p][$k] = $val->IdSuin;
                                break;
                            case 'numid':
                                $persona[$p][$k] = $val->Ci;
                                break;
                            case 'nombre':
                                $persona[$p][$k] = $val->PrimerNombre;
                                break;
                            case 'snombre':
                                $persona[$p][$k] = $val->SegundoNombre;
                                break;
                            case 'papel':
                                $persona[$p][$k] = $val->PrimerApellido;
                                break;
                            case 'sapel':
                                $persona[$p][$k] = $val->SegundoApellido;
                                break;
                            case 'sexo':
                                $persona[$p][$k] = $val->Sexo == 'M' ? 'Masculino' : 'Femenino';
                                break;
                            case 'tomo':
                                $persona[$p][$k] = $val->Tomo;
                                break;
                            case 'nompa':
                                $persona[$p][$k] = $val->NombrePadre;
                                break;
                            case 'nomma':
                                $persona[$p][$k] = $val->NombreMadre;
                                break;
                            case 'direccion':
                                $persona[$p][$k] = $val->Direccion->Dir;
                                break;
                            case 'idprovinciares':
                                $persona[$p][$k] = $val->Direccion->Provincia;
                                break;
                            case 'idmunicipiores':
                                $persona[$p][$k] = $val->Direccion->Municpio;
                                break;
                            case 'nacionalidad':
                                $persona[$p][$k] = $val->Nacionalidad;
                                break;
                            case 'idcolorojos':
                                    $persona[$p][$k] = ($val->ColorOjos != -1)?$val->ColorOjos:0;
                                break;
                            case 'idcolorpiel':
                                    $persona[$p][$k] = ($val->ColorPiel != -1)?$val->ColorPiel:0;
                                break;
                            case 'idtipodocidentidad':
                                $persona[$p][$k] = 1;
                                break;
                            case 'foto':
                                $persona[$p][$k] = $val->Foto;
                                break;
                            case 'edad':
                                $persona[$p][$k] = $val->Edad;
                                break;
                            case 'fechanacimiento':
                                $persona[$p][$k] = $val->FechaNacimiento;
                                break;
                            case 'nombreapellidos':
                                $persona[$p][$k] = $val->NombreApellidos;
                                break;
                        }
                    }
                }
            }
//            print_r('<pre>');
//            print_r($persona);die;
            return $persona;
        } catch (Exception $e) {
            throw  $e;
        }
    }

}